use vstd::prelude::*;

verus! {

fn copy(a: &Vec<u64>) -> (b: Vec<u64>)
    ensures
        b@ == a@,
{
    let mut b: Vec<u64> = Vec::with_capacity(a.len());

    for &x in a.iter()
        invariant
            b@ == a@.subrange(0, b@.len() as int),
            b@.len() <= a@.len(),
    {
        b.push(x);

        // Help the solver relate the pushed element to the next element of `a`.
        assert(b@.len() > 0);
        assert(b@[b@.len() as int - 1] == a@[b@.len() as int - 1]);
    }

    // At loop exit, lengths must match, so the subrange equality implies full equality.
    assert(b@.len() == a@.len());
    assert(a@.subrange(0, a@.len() as int) == a@);

    b
}

}

